import { mkdtempSync,readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { ResearchClient } from "research-explorer-core/client";
import { PUBLIC_SCHEMA_VERSION } from "research-explorer-core/contracts";
import { startCoreService } from "research-explorer-core/server";

const root=mkdtempSync(join(tmpdir(),"auto-research-capabilities-")),service=await startCoreService({databasePath:join(root,"research.db"),dataDir:join(root,"service")}),token=readFileSync(service.address.tokenFile,"utf8").trim(),client=await ResearchClient.connect({baseUrl:service.address.baseUrl,token}),actor={id:"user:external",kind:"user"},workspaceId="workspace:external";let sequence=0;const command=(projectId,type,payload)=>({schemaVersion:PUBLIC_SCHEMA_VERSION,commandId:`external-${++sequence}`,idempotencyKey:`external-${sequence}`,workspaceId,projectId,actor,issuedAt:new Date().toISOString(),type,payload});
try{const created=await client.execute(command(null,"project.create",{intent:{title:"External scientific client",direction:"Verify installed public scientific capabilities from a package-only client.",domain:"research methods",constraints:["public SDK"],allowedData:["fixture"],prohibitions:[],profile:"smoke",budget:{gpuHours:0.001,wallHours:1,diskGiB:1,modelCalls:1,knownCostUsd:0}}})),projectId=created.projectId,proposed=await client.execute(command(projectId,"question.propose",{question:{question:"Can an installed client invoke a bounded scientific capability through the service?",rationale:"The release package must include every transitive runtime module behind the public capability contract.",targetPopulation:"Installed package clients",intervention:"Public capability command",comparator:"Internal module import",primaryOutcome:"Accepted bounded invocation",scope:"One package-only novelty fixture",sourceIds:[]}})),questionId=proposed.data.question.id;await client.execute(command(projectId,"question.select",{questionId}));await client.execute(command(projectId,"scope.approve",{note:"External fixture."}));const catalog=await client.query({schemaVersion:PUBLIC_SCHEMA_VERSION,queryId:"external-catalog",type:"capability.catalog",workspaceId,projectId,actor}),invoked=await client.execute(command(projectId,"capability.invoke",{capability:"novelty-boundary",input:{coverageStatus:"complete",noveltyStatus:"unresolved",noveltyScope:null,comparisons:[],gaps:[]}}));if(catalog.status!=="ok"||catalog.data.capabilities.length!==7||invoked.status!=="accepted")throw new Error("Installed capability fixture failed");console.log(JSON.stringify({catalog:catalog.data.capabilities.length,invoke:invoked.status}));}finally{await service.close();}
